/* Keep navigation visible while browsing sections. */
header{position:sticky;top:0;z-index:100;backdrop-filter:blur(16px)}
html{scroll-padding-top:110px}
@media(max-width:650px){html{scroll-padding-top:96px}}

/* GS identity and a softer, atmospheric Riptide backdrop. */
.gs-logo{width:67px;height:44px;flex-shrink:0;filter:drop-shadow(0 4px 12px #0003)}
.hero-glow{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 85% 20%,#85b0e70a,transparent 55%)}
.hero-art{background:radial-gradient(ellipse at 60% 50%,#304b6c22,transparent 70%);isolation:isolate}
.tide-aura{position:absolute;inset:25px -40px 20px 0;background:radial-gradient(ellipse at 55% 42%,#7ca4d638,transparent 55%);filter:blur(35px)}
.riptide{color:#cedbeb;text-shadow:0 3px 0 #74859b,0 18px 55px #0006;transform:rotate(-8deg);z-index:3}
.tide-swell{position:absolute;width:110%;height:250px;left:0;top:300px;border-radius:55% 45% 35% 65%;transform:rotate(-24deg);background:linear-gradient(145deg,#9abeeb99 0%,#7293bc77 22%,#24374e66 55%,transparent 78%);box-shadow:inset 0 15px 35px #a3ccff1a;filter:blur(1px);z-index:1}
.swell-two{left:25%;top:365px;transform:rotate(-32deg);background:linear-gradient(135deg,#8aacd777,#22354d99 45%,transparent 75%);height:210px;z-index:2}
.coordinate{color:#a5b4c8}.art-label{z-index:4}
@media(max-width:650px){.gs-logo{width:53px;height:35px}.tide-swell{height:155px;top:170px;left:-5%}.swell-two{top:220px;left:25%;height:140px}.tide-aura{inset:0 5%}}

.gs-logo{width:49px;height:49px}@media(max-width:650px){.gs-logo{width:40px;height:40px}}

/* Ocean-blue Riptide design with the supplied background artwork. */
:root{--bg:#080f1e;--panel:#111f36;--line:#23334d;--muted:#a5b4cc;--lime:#84c7ff;--teal:#5b9fe4}
body{background:var(--bg);color:#eff5ff}
header{background:#080f1ef2;border-color:var(--line)}
.hero{isolation:isolate;background:#080f1e;min-height:730px}
.hero::before{content:"";position:absolute;z-index:-2;inset:0 0 0 27%;background-image:linear-gradient(90deg,#080f1e 0%,#080f1e44 38%,#080f1e08 75%),linear-gradient(0deg,#080f1e 0%,#080f1e00 30%,#080f1e22 100%),url("data:image/png;base64,");background-position:center,right center,right center;background-size:cover;background-repeat:no-repeat;opacity:.9}
.hero::after{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;background:linear-gradient(90deg,#080f1e 0%,#080f1ef5 22%,#080f1e9c 48%,#080f1e00 78%)}
.hero-copy{width:61%;max-width:900px}.hero h1{text-shadow:0 5px 35px #0006}.hero-copy>p{color:#c4d0e4;text-shadow:0 2px 10px #080f1e}
.hero-meta,.hero-bottom{color:#a7b9d3}.hero-bottom{margin-top:85px;border-color:#8bbfff26}
.primary{background:#84c7ff;color:#0b213b}.button:hover{background:#b2deff}
.nav-download{border-color:#4c6d97}.status-strip{background:#13253d}.status-strip p{color:#bbcce1}
.download{background:#0d192c}.download-panel{background:#14243b;border-color:#35577d}.pill{border-color:#4c7198;color:#9dd3ff}
.step-tag{color:#bdcde1}.offline-note{background:#111f34}.offline-note b{color:#dceaff}
.rewards{background:#0b1627}.reward-list .knife{border-color:#4e7caf}
.sponsor{background:#acd6ff;color:#0a2340}.sponsor .eyebrow{color:#345778}.sponsor p{color:#345778}.sponsor strong{color:#142f4e}.sponsor h2 a{border-color:#6a9fce}
@media(max-width:950px){.hero-copy{width:76%}.hero::before{left:17%;opacity:.75}.hero::after{background:linear-gradient(90deg,#080f1e 0%,#080f1ee0 30%,#080f1e55 73%)} }
@media(max-width:650px){.hero{min-height:850px;padding-top:48px}.hero-copy{width:100%}.hero::before{inset:400px 0 0;background-image:linear-gradient(180deg,#080f1e 0%,#080f1e00 30%,#080f1e22 72%,#080f1e 100%),url("data:image/png;base64,");background-position:center;background-size:cover;opacity:.85}.hero::after{background:linear-gradient(180deg,#080f1e00 35%,#080f1e33 62%,#080f1e00 80%)}.hero-bottom{margin-top:330px;font-size:7px}.hero-meta{color:#b0c2da}}

/* Angular, joined GS identity. */
.gs-logo{width:60px;height:50px;filter:drop-shadow(0 4px 10px #0003)}@media(max-width:650px){.gs-logo{width:48px;height:40px}}
